def _term_div(self):
    zm = self.ring.zero_monom
    domain = self.ring.domain
    domain_quo = domain.quo
    monomial_div = self.ring.monomial_div

    if domain.is_Field:
        def term_div(a_lm_a_lc, b_lm_b_lc):
            a_lm, a_lc = a_lm_a_lc
            b_lm, b_lc = b_lm_b_lc
            if b_lm == zm: # apparently this is a very common case
                monom = a_lm
            else:
                monom = monomial_div(a_lm, b_lm)
            if monom is not None:
                return monom, domain_quo(a_lc, b_lc)
            else:
                return None
    else:
        def term_div(a_lm_a_lc, b_lm_b_lc):
            a_lm, a_lc = a_lm_a_lc
            b_lm, b_lc = b_lm_b_lc
            if b_lm == zm: # apparently this is a very common case
                monom = a_lm
            else:
                monom = monomial_div(a_lm, b_lm)
            if not (monom is None or a_lc % b_lc):
                return monom, domain_quo(a_lc, b_lc)
            else:
                return None

    return term_div

def div(self, fv):
    """Division algorithm, see [CLO] p64.

    fv array of polynomials
       return qv, r such that
       self = sum(fv[i]*qv[i]) + r

    All polynomials are required not to be Laurent polynomials.

    Examples
    ========

    >>> from sympy.polys.rings import ring
    >>> from sympy.polys.domains import ZZ

    >>> _, x, y = ring('x, y', ZZ)
    >>> f = x**3
    >>> f0 = x - y**2
    >>> f1 = x - y
    >>> qv, r = f.div((f0, f1))
    >>> qv[0]
    x**2 + x*y**2 + y**4
    >>> qv[1]
    0
    >>> r
    y**6

    """
    ring = self.ring
    ret_single = False
    if isinstance(fv, PolyElement):
        ret_single = True
        fv = [fv]
    if not all(fv):
        raise ZeroDivisionError("polynomial division")
    if not self:
        if ret_single:
            return ring.zero, ring.zero
        else:
            return [], ring.zero
    for f in fv:
        if f.ring != ring:
            raise ValueError('self and f must have the same ring')
    s = len(fv)
    qv = [ring.zero for i in range(s)]
    p = self.copy()
    r = ring.zero
    term_div = self._term_div()
    expvs = [fx.leading_expv() for fx in fv]
    while p:
        i = 0
        divoccurred = 0
        while i < s and divoccurred == 0:
            expv = p.leading_expv()
            term = term_div((expv, p[expv]), (expvs[i], fv[i][expvs[i]]))
            if term is not None:
                expv1, c = term
                qv[i] = qv[i]._iadd_monom((expv1, c))
                p = p._iadd_poly_monom(fv[i], (expv1, -c))
                divoccurred = 1
            else:
                i += 1
        if not divoccurred:
            expv =  p.leading_expv()
            r = r._iadd_monom((expv, p[expv]))
            del p[expv]
    if expv == ring.zero_monom:
        r += p
    if ret_single:
        if not qv:
            return ring.zero, r
        else:
            return qv[0], r
    else:
        return qv, r

def rem(self, G):
    f = self
    if isinstance(G, PolyElement):
        G = [G]
    if not all(G):
        raise ZeroDivisionError("polynomial division")
    ring = f.ring
    domain = ring.domain
    zero = domain.zero
    monomial_mul = ring.monomial_mul
    r = ring.zero
    term_div = f._term_div()
    ltf = f.LT
    f = f.copy()
    get = f.get
    while f:
        for g in G:
            tq = term_div(ltf, g.LT)
            if tq is not None:
                m, c = tq
                for mg, cg in g.iterterms():
                    m1 = monomial_mul(mg, m)
                    c1 = get(m1, zero) - c*cg
                    if not c1:
                        del f[m1]
                    else:
                        f[m1] = c1
                ltm = f.leading_expv()
                if ltm is not None:
                    ltf = ltm, f[ltm]

                break
        else:
            ltm, ltc = ltf
            if ltm in r:
                r[ltm] += ltc
            else:
                r[ltm] = ltc
            del f[ltm]
            ltm = f.leading_expv()
            if ltm is not None:
                ltf = ltm, f[ltm]

    return r

def quo(f, G):
    return f.div(G)[0]

def exquo(f, G):
    q, r = f.div(G)

    if not r:
        return q
    else:
        raise ExactQuotientFailed(f, G)

def _iadd_monom(self, mc):
    """add to self the monomial coeff*x0**i0*x1**i1*...
    unless self is a generator -- then just return the sum of the two.

    mc is a tuple, (monom, coeff), where monomial is (i0, i1, ...)

    Examples
    ========

    >>> from sympy.polys.rings import ring
    >>> from sympy.polys.domains import ZZ

    >>> _, x, y = ring('x, y', ZZ)
    >>> p = x**4 + 2*y
    >>> m = (1, 2)
    >>> p1 = p._iadd_monom((m, 5))
    >>> p1
    x**4 + 5*x*y**2 + 2*y
    >>> p1 is p
    True
    >>> p = x
    >>> p1 = p._iadd_monom((m, 5))

def monic(f):
    """Divides all coefficients by the leading coefficient. """
    if not f:
        return f
    else:
        return f.quo_ground(f.LC)

def mul_ground(f, x):
    if not x:
        return f.ring.zero

    terms = [ (monom, coeff*x) for monom, coeff in f.iterterms() ]
    return f.new(terms)

def mul_monom(f, monom):
    monomial_mul = f.ring.monomial_mul
    terms = [ (monomial_mul(f_monom, monom), f_coeff) for f_monom, f_coeff in f.items() ]
    return f.new(terms)

def mul_term(f, term):
    monom, coeff = term

    if not f or not coeff:
        return f.ring.zero
    elif monom == f.ring.zero_monom:
        return f.mul_ground(coeff)

    monomial_mul = f.ring.monomial_mul
    terms = [ (monomial_mul(f_monom, monom), f_coeff*coeff) for f_monom, f_coeff in f.items() ]
    return f.new(terms)

def quo_ground(f, x):
    domain = f.ring.domain

    if not x:
        raise ZeroDivisionError('polynomial division')
    if not f or x == domain.one:
        return f

    if domain.is_Field:
        quo = domain.quo
        terms = [ (monom, quo(coeff, x)) for monom, coeff in f.iterterms() ]
    else:
        terms = [ (monom, coeff // x) for monom, coeff in f.iterterms() if not (coeff % x) ]

    return f.new(terms)

def quo_term(f, term):
    monom, coeff = term

    if not coeff:
        raise ZeroDivisionError("polynomial division")
    elif not f:
        return f.ring.zero
    elif monom == f.ring.zero_monom:
        return f.quo_ground(coeff)

    term_div = f._term_div()

    terms = [ term_div(t, term) for t in f.iterterms() ]
    return f.new([ t for t in terms if t is not None ])

